from dataclasses import dataclass

CHECK_PASS = 0.95


@dataclass(frozen=True)
class CheckResult:
    """Share of check-world states where the trained policy picks the best action."""

    method: str
    world: str
    agreement: float
    passed: bool

    def __post_init__(self) -> None:
        if self.passed != (self.agreement >= CHECK_PASS):
            raise ValueError(
                f"passed must be agreement >= {CHECK_PASS}: got {self.passed} at {self.agreement}"
            )


class CheckFailedError(RuntimeError):
    """A method failed its check world, so the batch is refused before any run starts."""

    def __init__(self, result: CheckResult) -> None:
        super().__init__(
            f"method check failed: {result.method} on {result.world} "
            f"agreed on {result.agreement:.0%} of states (needs {CHECK_PASS:.0%})"
        )
        self.result = result

