            "max_steps": POS,
            "measures": arr(ref("MeasureSpec")),
            "sight": nullable(NUM),
        }
    ),
    "Step": obj(
        {
            "obs": arr(arr(NUM)),
            "rewards": arr(NUM),
            "active": arr(BOOL),
            "done": BOOL,
            "truncated": BOOL,
        }
    ),
    "EpisodeResult": obj(
        {
            "seed": INT,
            "length": NAT,
