            "kind": STR,
            "x": NUM,
            "y": NUM,
            "size": NUM,
            "team": nullable(STR),
            "agent": nullable(NAT),
        }
    ),
    "DrawState": obj({"width": NUM, "height": NUM, "objects": arr(ref("Drawable"))}),
    "Frame": obj(
        {"step": NAT, "draw": ref("DrawState"), "scores": mapping(NUM), "rewards": arr(NUM)}
    ),
    "Episode": obj(
