            "hit_step_limit": BOOL,
        }
    ),
    "Output": obj(
        {"path": STR, "kind": {"enum": ["chart", "video", "writeup"]}, "made_from": arr(STR)}
    ),
    "Settings": mapping({"type": ["integer", "number", "string", "boolean"]}),
    "MethodConfig": obj({"method": {"enum": ["dqn", "ppo"]}, "settings": ref("Settings")}),
    "RunConfig": obj(
        {
            "name": STR,
            "world": STR,
