            "learned_mean": NUM,
            "baseline_mean": NUM,
            "difference": NUM,
            "p_raw": P,
            "p_holm": P,
            "rejected": BOOL,
        }
    ),
    "Verdict": obj({"beats_baselines": BOOL, "failing_runs": arr(STR), "runs_needed": NAT}),
    "Summary": obj(
        {
            "world": STR,
            "variant": STR,
            "team": STR,
