            "learned_mean": NUM,
            "learned_range": arr(NUM, 2),
            "run_means": mapping(NUM),
            "random_mean": NUM,
            "rule_mean": NUM,
            "comparisons": arr(ref("Comparison")),
            "verdict": ref("Verdict"),
