"""Generate the M1 contract fixtures (schemas, samples, recordings) into tests/contracts."""

import json
import sys
from pathlib import Path

OUT = Path(sys.argv[1])


def write(folder, rel, data):
    path = OUT / folder / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=1) + "\n")


# ------------------------------------------------------------------ schemas
NUM = {"type": "number"}
INT = {"type": "integer"}
NAT = {"type": "integer", "minimum": 0}
POS = {"type": "integer", "minimum": 1}
STR = {"type": "string"}
BOOL = {"type": "boolean"}
P = {"type": "number", "minimum": 0, "maximum": 1}
DIRECTION = {"enum": ["higher", "lower"]}


def obj(props):
    return {
        "type": "object",
        "properties": props,
        "required": list(props),
        "additionalProperties": False,
    }


def arr(items, n=None):
    d = {"type": "array", "items": items}
    if n is not None:
        d["minItems"] = d["maxItems"] = n
    return d


def ref(name):
    return {"$ref": f"#/$defs/{name}"}


def nullable(s):
    return {"anyOf": [s, {"type": "null"}]}


def mapping(values):
    return {"type": "object", "additionalProperties": values}


DEFS = {
    "ActionSpace": {
        "anyOf": [
            obj({"kind": {"const": "discrete"}, "n": POS}),
            obj({"kind": {"const": "box"}, "dims": POS, "low": NUM, "high": NUM}),
        ]
    },
    "TeamSpec": obj({"name": STR, "agents": arr(NAT), "score_name": STR, "direction": DIRECTION}),
    "MeasureSpec": obj({"name": STR, "team": STR, "direction": DIRECTION}),
    "WorldSpec": obj(
        {
            "world": STR,
            "variant": STR,
            "agents": arr(STR),
            "teams": arr(ref("TeamSpec")),
            "obs_len": POS,
            "action": ref("ActionSpace"),
            "max_steps": POS,
            "measures": arr(ref("MeasureSpec")),
            "sight": nullable(NUM),
        }
    ),
    "Step": obj(
        {
            "obs": arr(arr(NUM)),
            "rewards": arr(NUM),
            "active": arr(BOOL),
            "done": BOOL,
            "truncated": BOOL,
        }
    ),
    "EpisodeResult": obj(
        {
            "seed": INT,
            "length": NAT,
            "scores": mapping(NUM),
            "team_rewards": mapping(NUM),
            "measures": mapping(NUM),
        }
    ),
    "Drawable": obj(
        {
            "kind": STR,
            "x": NUM,
            "y": NUM,
            "size": NUM,
            "team": nullable(STR),
            "agent": nullable(NAT),
        }
    ),
    "DrawState": obj({"width": NUM, "height": NUM, "objects": arr(ref("Drawable"))}),
    "Frame": obj(
        {"step": NAT, "draw": ref("DrawState"), "scores": mapping(NUM), "rewards": arr(NUM)}
    ),
    "Episode": obj(
        {
            "result": ref("EpisodeResult"),
            "frames": nullable(arr(ref("Frame"))),
            "hit_step_limit": BOOL,
        }
    ),
    "Output": obj(
        {"path": STR, "kind": {"enum": ["chart", "video", "writeup"]}, "made_from": arr(STR)}
    ),
    "Settings": mapping({"type": ["integer", "number", "string", "boolean"]}),
    "MethodConfig": obj({"method": {"enum": ["dqn", "ppo"]}, "settings": ref("Settings")}),
    "RunConfig": obj(
        {
            "name": STR,
            "world": STR,
            "variant": STR,
            "methods": mapping(ref("MethodConfig")),
            "seed": NAT,
            "budget": POS,
            "check_settings": mapping(ref("Settings")),
            "device": STR,
        }
    ),
    "BaselineMeans": obj(
        {"world": STR, "variant": STR, "random": mapping(NUM), "rule": mapping(NUM)}
    ),
    "Transition": obj(
        {
            "obs": arr(arr(NUM)),
            "actions": arr({"anyOf": [INT, arr(NUM)]}),
            "rewards": arr(NUM),
            "next_obs": arr(arr(NUM)),
            "done": BOOL,
            "truncated": BOOL,
            "active": arr(BOOL),
        }
    ),
    "CheckResult": obj({"method": STR, "world": STR, "agreement": P, "passed": BOOL}),
    "Failure": obj({"step": NAT, "value": NUM, "checkpoint": STR}),
    "RunRecord": obj(
        {
            "config": ref("RunConfig"),
            "spec": ref("WorldSpec"),
            "started": STR,
            "ended": nullable(STR),
            "status": {"enum": ["running", "finished", "incomplete", "failed"]},
            "failure": nullable(ref("Failure")),
            "path": STR,
        }
    ),
    "EvalPoint": obj({"step": NAT, "scores": mapping(NUM), "measures": mapping(NUM)}),
    "Checkpoint": obj(
        {
            "run": STR,
            "pct": {"enum": list(range(0, 101, 10))},
            "step": NAT,
            "spec": ref("WorldSpec"),
            "methods": mapping(ref("MethodConfig")),
            "state": mapping({"type": "object"}),
            "path": STR,
        }
    ),
    "Progress": obj(
        {
            "step": NAT,
            "budget": POS,
            "latest": nullable(ref("EvalPoint")),
            "elapsed": {"type": "number", "minimum": 0},
            "status": STR,
        }
    ),
    "Comparison": obj(
        {
            "baseline": {"enum": ["random", "rule"]},
            "team": STR,
            "learned_mean": NUM,
            "baseline_mean": NUM,
            "difference": NUM,
            "p_raw": P,
            "p_holm": P,
            "rejected": BOOL,
        }
    ),
    "Verdict": obj({"beats_baselines": BOOL, "failing_runs": arr(STR), "runs_needed": NAT}),
    "Summary": obj(
        {
            "world": STR,
            "variant": STR,
            "team": STR,
            "runs": arr(STR),
            "learned_mean": NUM,
            "learned_range": arr(NUM, 2),
            "run_means": mapping(NUM),
            "random_mean": NUM,
            "rule_mean": NUM,
            "comparisons": arr(ref("Comparison")),
            "verdict": ref("Verdict"),
            "collapse": nullable(NAT),
        }
    ),
}


def refs(node, found):
    if isinstance(node, dict):
        if "$ref" in node:
            name = node["$ref"].rsplit("/", 1)[1]
            if name not in found:
                found.add(name)
                refs(DEFS[name], found)
        for value in node.values():
            refs(value, found)
    elif isinstance(node, list):
        for value in node:
            refs(value, found)


def schema(folder, type_name):
    found = {type_name}
    refs(DEFS[type_name], found)
    write(
        folder,
        "schema.json",
        {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": folder,
            "$ref": f"#/$defs/{type_name}",
            "$defs": {name: DEFS[name] for name in sorted(found)},
        },
    )


# ------------------------------------------------------------------ specs
def team(name, agents, score, direction):
    return {"name": name, "agents": agents, "score_name": score, "direction": direction}


def snake_spec(max_steps=1000):
    return {
        "world": "snake",
        "variant": "default",
        "agents": ["snake"],
        "teams": [team("snake", [0], "food eaten", "higher")],
        "obs_len": 12,
        "action": {"kind": "discrete", "n": 3},
        "max_steps": max_steps,
        "measures": [],
        "sight": None,
    }


FISH_LOCAL = {
    "world": "fish",
    "variant": "local",
    "agents": [f"fish-{i}" for i in range(8)],
    "teams": [team("fish", list(range(8)), "hits per fish", "lower")],
    "obs_len": 44,
    "action": {"kind": "box", "dims": 2, "low": -1.0, "high": 1.0},
    "max_steps": 1000,
    "measures": [],
    "sight": 3.0,
}
PREY_OBS = 40
PREY = {
    "world": "prey",
    "variant": "default",
    "agents": [f"prey-{i}" for i in range(6)] + ["predator-0", "predator-1"],
    "teams": [
        team("prey", list(range(6)), "pellets per prey", "higher"),
        team("predator", [6, 7], "prey caught", "higher"),
    ],
    "obs_len": PREY_OBS,
    "action": {"kind": "box", "dims": 2, "low": -1.0, "high": 1.0},
    "max_steps": 1000,
    "measures": [{"name": "survivors", "team": "prey", "direction": "higher"}],
    "sight": 4.0,
}
CORRIDOR_SPEC = {
    "world": "check-discrete",
    "variant": "default",
    "agents": ["agent"],
    "teams": [team("agent", [0], "return", "higher")],
    "obs_len": 6,
    "action": {"kind": "discrete", "n": 2},
    "max_steps": 50,
    "measures": [],
    "sight": None,
}
POINT_SPEC = {
    "world": "check-continuous",
    "variant": "default",
    "agents": ["agent"],
    "teams": [team("agent", [0], "return", "higher")],
    "obs_len": 1,
    "action": {"kind": "box", "dims": 1, "low": -1.0, "high": 1.0},
    "max_steps": 20,
    "measures": [],
    "sight": None,
}

# ------------------------------------------------------------------ snake simulation
HEADINGS = [(0, -1), (1, 0), (0, 1), (-1, 0)]  # up, right, down, left


def blocked(cell, body):
    x, y = cell
    return not (0 <= x < 10 and 0 <= y < 10) or cell in body[:-1]


def snake_obs(body, heading, food):
    head = body[0]

    def danger(h):
        dx, dy = HEADINGS[h % 4]
        return float(blocked((head[0] + dx, head[1] + dy), body))

    fx, fy = food[0] - head[0], food[1] - head[1]
    return [
        danger(heading),
        danger(heading - 1),
        danger(heading + 1),
        *[float(i == heading) for i in range(4)],
        float(fy < 0),
        float(fx > 0),
        float(fy > 0),
        float(fx < 0),
        float(len(body)),
    ]


def snake_draw(body, food):
    objects = [
        {"kind": "snake-head", "x": float(body[0][0]), "y": float(body[0][1]), "size": 1.0,
         "team": "snake", "agent": 0}
    ]
    objects += [
        {"kind": "snake-body", "x": float(x), "y": float(y), "size": 1.0, "team": "snake",
         "agent": None}
        for x, y in body[1:]
    ]
    objects.append(
        {"kind": "food", "x": float(food[0]), "y": float(food[1]), "size": 1.0, "team": None,
         "agent": None}
    )
    return {"width": 10.0, "height": 10.0, "objects": objects}


def snake_episode(seed, body, heading, foods, actions, max_steps):
    """Index i: the Step, DrawState and running EpisodeResult after i steps."""
    foods = list(foods)
    food = foods.pop(0)
    eaten, total = 0, 0.0
    out = []

    def record(actions_taken, reward, done, truncated, length):
        out.append(
            {
                "actions": actions_taken,
                "step": {
                    "obs": [snake_obs(body, heading, food)],
                    "rewards": [reward],
                    "active": [True],
                    "done": done,
                    "truncated": truncated,
                },
                "draw": snake_draw(body, food),
                "result": {
                    "seed": seed,
                    "length": length,
                    "scores": {"snake": float(eaten)},
                    "team_rewards": {"snake": total},
                    "measures": {},
                },
            }
        )

    record(None, 0.0, False, False, 0)
    for i, action in enumerate(actions, start=1):
        heading = (heading + {0: 0, 1: -1, 2: 1}[action]) % 4
        dx, dy = HEADINGS[heading]
        head = (body[0][0] + dx, body[0][1] + dy)
        assert not blocked(head, body)
        body.insert(0, head)
        reward = 0.0
        if head == food:
            eaten += 1
            reward = 1.0
            food = foods.pop(0)
        else:
            body.pop()
        total += reward
        truncated = i == max_steps
        record([action], reward, truncated, truncated, i)
    return out


EP42 = snake_episode(42, [(5, 5), (5, 6), (5, 7)], 0, [(8, 4), (2, 7)], [0, 2, 0, 0, 2], 5)
EP7 = snake_episode(7, [(5, 5), (5, 6), (5, 7)], 0, [(5, 3), (1, 1)], [0, 0, 0], 3)


def frames(episode):
    return [
        {
            "step": i,
            "draw": entry["draw"],
            "scores": entry["result"]["scores"],
            "rewards": entry["step"]["rewards"],
        }
        for i, entry in enumerate(episode)
    ]


# ------------------------------------------------------------------ check worlds
def corridor_episode(seed, start, actions):
    out = []
    state, total = start, 0.0

    def draw(s):
        return {
            "width": 8.0,
            "height": 1.0,
            "objects": [
                {"kind": "exit", "x": 0.0, "y": 0.0, "size": 1.0, "team": None, "agent": None},
                {"kind": "exit", "x": 7.0, "y": 0.0, "size": 1.0, "team": None, "agent": None},
                {"kind": "agent", "x": float(s + 1), "y": 0.0, "size": 1.0, "team": "agent",
                 "agent": 0},
            ],
        }

    def entry(actions_taken, reward, done, length, s):
        obs = [float(i == s) for i in range(6)] if 0 <= s <= 5 else [0.0] * 6
        return {
            "actions": actions_taken,
            "step": {"obs": [obs], "rewards": [reward], "active": [True], "done": done,
                     "truncated": False},
            "draw": draw(s),
            "result": {"seed": seed, "length": length, "scores": {"agent": total},
                       "team_rewards": {"agent": total}, "measures": {}},
        }

    out.append(entry(None, 0.0, False, 0, state))
    for i, action in enumerate(actions, start=1):
        state += 1 if action == 1 else -1
        reward = 1.0 if state == 6 else 0.8 if state == -1 else 0.0
        total += reward
        out.append(entry([action], reward, state in (-1, 6), i, state))
    return out


CORRIDOR = corridor_episode(0, 2, [1, 1, 1, 1])
CORRIDOR3 = corridor_episode(1, 3, [1, 1, 1])


def point_episode(seed, start, pushes):
    out = []
    x, total = start, 0.0

    def entry(actions_taken, reward, done, length):
        return {
            "actions": actions_taken,
            "step": {"obs": [[x]], "rewards": [reward], "active": [True], "done": done,
                     "truncated": False},
            "draw": {"width": 2.0, "height": 1.0, "objects": [
                {"kind": "target", "x": 1.0, "y": 0.5, "size": 0.1, "team": None, "agent": None},
                {"kind": "agent", "x": round(x + 1.0, 6), "y": 0.5, "size": 0.1,
                 "team": "agent", "agent": 0},
            ]},
            "result": {"seed": seed, "length": length, "scores": {"agent": total},
                       "team_rewards": {"agent": total}, "measures": {}},
        }

    out.append(entry(None, 0.0, False, 0))
    for i, push in enumerate(pushes, start=1):
        x = round(x + 0.2 * push, 6)
        reward = round(-abs(x), 6)
        total = round(total + reward, 6)
        out.append(entry([[float(push)]], reward, abs(x) < 0.05, i))
    return out


POINT = point_episode(0, 0.6, [-1, -1, -1])

# ------------------------------------------------------------------ configs
DQN_DEFAULTS = {
    "lr": 0.001,
    "gamma": 0.99,
    "hidden": 64,
    "epsilon_start": 1.0,
    "epsilon_end": 0.05,
    "epsilon_decay_steps": 10000,
}
PPO_SETTINGS = {"lr": 0.0001, "gamma": 0.99, "hidden": 64, "rollout_steps": 2048}
DQN = {"method": "dqn", "settings": DQN_DEFAULTS}
CHECK_SETTINGS = {"dqn": {"epsilon_decay_steps": 500}}


def snake_config(seed, budget=2000):
    return {
        "name": f"snake-default-s{seed}",
        "world": "snake",
        "variant": "default",
        "methods": {"snake": DQN},
        "seed": seed,
        "budget": budget,
        "check_settings": CHECK_SETTINGS,
        "device": "cpu",
    }


PREY_CONFIG = {
    "name": "prey-default-s1",
    "world": "prey",
    "variant": "default",
    "methods": {
        "prey": {"method": "ppo", "settings": PPO_SETTINGS},
        "predator": {"method": "ppo", "settings": {**PPO_SETTINGS, "lr": 0.0003}},
    },
    "seed": 1,
    "budget": 200000,
    "check_settings": {"ppo": {"rollout_steps": 256}},
    "device": "cpu",
}


# ------------------------------------------------------------------ runs
def run_folder(name):
    return f"runs/snake/default/{name}"


def eval_points(seed):
    points = []
    for k in range(21):
        step = 100 * k
        points.append(
            {"step": step, "scores": {"snake": round((8 + 0.3 * seed) * k / 20, 4)},
             "measures": {}}
        )
    return points


def episodes(seed):
    lengths = [37, 52, 61, 88, 140, 212]
    return [
        {"seed": 1000 * seed + i, "length": n, "scores": {"snake": float(i + seed // 2)},
         "team_rewards": {"snake": float(i + seed // 2) - 1.0}, "measures": {}}
        for i, n in enumerate(lengths)
    ]


def checkpoint(name, pct, budget, spec=None):
    return {
        "run": name,
        "pct": pct,
        "step": budget * pct // 100,
        "spec": spec or snake_spec(),
        "methods": {"snake": DQN},
        "state": {"snake": {"observed": budget * pct // 100}},
        "path": f"{run_folder(name)}/checkpoints/ckpt_{pct}.pt",
    }


def record(seed, status, ended, failure=None, budget=2000):
    name = f"snake-default-s{seed}"
    return {
        "config": snake_config(seed, budget),
        "spec": snake_spec(),
        "started": "2026-10-17T09:00:00+00:00",
        "ended": ended,
        "status": status,
        "failure": failure,
        "path": run_folder(name),
    }


def run_recording(seed, status="finished"):
    name = f"snake-default-s{seed}"
    finished = status == "finished"
    evals = eval_points(seed) if finished else eval_points(seed)[:8]
    pcts = [0, 50, 100] if finished else [0]
    return {
        "record": record(seed, status, "2026-10-17T09:41:00+00:00" if finished else None),
        "episodes": episodes(seed) if finished else episodes(seed)[:2],
        "evals": evals,
        "checkpoints": [checkpoint(name, pct, 2000) for pct in pcts],
    }


# ------------------------------------------------------------------ write: core
def core():
    schema("core.ActionSpace", "ActionSpace")
    write("core.ActionSpace", "samples/snake.json", {"kind": "discrete", "n": 3})
    write("core.ActionSpace", "samples/fish.json",
