    write("core.TeamSpec", "samples/prey_predator.json", PREY["teams"][1])

    schema("core.WorldSpec", "WorldSpec")
    write("core.WorldSpec", "samples/snake_default.json", snake_spec())
    write("core.WorldSpec", "samples/fish_local.json", FISH_LOCAL)
