    schema("core.Step", "Step")
    write("core.Step", "samples/snake_mid_episode.json", EP42[2]["step"])
    obs = [[round(0.01 * (a + 1) * (j % 7), 4) for j in range(PREY_OBS)] for a in range(8)]
    obs[2] = [0.0] * PREY_OBS
    write("core.Step", "samples/prey_one_caught.json", {
