"""How the M1 contract fixtures were made: schemas, samples and recordings (M1-T01).

Run once by the interface task (`python3 tests/contracts/generate.py`); the JSON it wrote is the
frozen contract (CR-09), so this file documents it and is not run again. The snake episodes are
simulated here by the SNAKE-01 to SNAKE-06 rules on a 10 x 10 grid (actions: 0 straight, 1 left,
2 right; headings up, right, down, left), so steps, observations, frames and scores agree.
The corridor check world uses action 0 = left, 1 = right (AD-09).
"""

import json
from pathlib import Path

OUT = Path(__file__).parent


def write(folder, rel, data):
    path = OUT / folder / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=1) + "\n")


# ------------------------------------------------------------------ schemas (JSON Schema)
NUM = {"type": "number"}
INT = {"type": "integer"}
NAT = {"type": "integer", "minimum": 0}
POS = {"type": "integer", "minimum": 1}
STR = {"type": "string"}
BOOL = {"type": "boolean"}
P = {"type": "number", "minimum": 0, "maximum": 1}
DIRECTION = {"enum": ["higher", "lower"]}


def obj(props):
    return {
        "type": "object",
        "properties": props,
        "required": list(props),
        "additionalProperties": False,
    }


def arr(items, n=None):
    d = {"type": "array", "items": items}
    if n is not None:
        d["minItems"] = d["maxItems"] = n
    return d


def ref(name):
    return {"$ref": f"#/$defs/{name}"}


def nullable(s):
    return {"anyOf": [s, {"type": "null"}]}


def mapping(values):
    return {"type": "object", "additionalProperties": values}


DEFS = {
    "ActionSpace": {
        "anyOf": [
            obj({"kind": {"const": "discrete"}, "n": POS}),
            obj({"kind": {"const": "box"}, "dims": POS, "low": NUM, "high": NUM}),
        ]
    },
    "TeamSpec": obj({"name": STR, "agents": arr(NAT), "score_name": STR, "direction": DIRECTION}),
    "MeasureSpec": obj({"name": STR, "team": STR, "direction": DIRECTION}),
