# ------------------------------------------------------------------ snake simulation
HEADINGS = [(0, -1), (1, 0), (0, 1), (-1, 0)]  # up, right, down, left
TURNS = {0: 0, 1: -1, 2: 1}  # straight, left, right


def blocked(cell, body):
    x, y = cell
    return not (0 <= x < 10 and 0 <= y < 10) or cell in body[:-1]


def snake_obs(body, heading, food):
    """Danger straight, left, right; heading one-hot; food up, right, down, left; length."""
    head = body[0]

    def danger(h):
        dx, dy = HEADINGS[h % 4]
        return float(blocked((head[0] + dx, head[1] + dy), body))

    fx, fy = food[0] - head[0], food[1] - head[1]
    return [
        danger(heading),
        danger(heading - 1),
        danger(heading + 1),
        *[float(i == heading) for i in range(4)],
        float(fy < 0),
        float(fx > 0),
        float(fy > 0),
        float(fx < 0),
        float(len(body)),
    ]


def cell(kind, x, y, team_name, agent):
    return {
        "kind": kind,
        "x": float(x),
        "y": float(y),
        "size": 1.0,
        "team": team_name,
        "agent": agent,
    }


def snake_draw(body, food):
    head = [cell("snake-head", *body[0], "snake", 0)]
    rest = [cell("snake-body", x, y, "snake", None) for x, y in body[1:]]
    return {
        "width": 10.0,
        "height": 10.0,
        "objects": [*head, *rest, cell("food", *food, None, None)],
    }


def snake_entry(seed, state, actions_taken, reward, length, truncated):
    body, heading, food, eaten, total = state
    return {
        "actions": actions_taken,
        "step": {
            "obs": [snake_obs(body, heading, food)],
            "rewards": [reward],
            "active": [True],
            "done": truncated,
            "truncated": truncated,
        },
        "draw": snake_draw(body, food),
        "result": {
            "seed": seed,
            "length": length,
            "scores": {"snake": float(eaten)},
            "team_rewards": {"snake": total},
            "measures": {},
        },
    }


def snake_episode(seed, foods, actions, max_steps):
    """Index i: the Step, DrawState and running EpisodeResult after i steps from the centre."""
    body, heading, foods = [(5, 5), (5, 6), (5, 7)], 0, list(foods)
    food, eaten, total = foods.pop(0), 0, 0.0
    out = [snake_entry(seed, (body, heading, food, eaten, total), None, 0.0, 0, False)]
    for i, action in enumerate(actions, start=1):
        heading = (heading + TURNS[action]) % 4
        head = (body[0][0] + HEADINGS[heading][0], body[0][1] + HEADINGS[heading][1])
        assert not blocked(head, body)
        body.insert(0, head)
        reward = float(head == food)
        if reward:
            eaten, food = eaten + 1, foods.pop(0)
        else:
            body.pop()
        total += reward
        state = (body, heading, food, eaten, total)
        out.append(snake_entry(seed, state, [action], reward, i, i == max_steps))
    return out


