def point_entry(seed, actions_taken, reward, length, x, total):
    return {
        "actions": actions_taken,
        "step": {
            "obs": [[x]],
            "rewards": [reward],
            "active": [True],
            "done": length > 0 and abs(x) < 0.05,
            "truncated": False,
        },
        "draw": {
            "width": 2.0,
            "height": 1.0,
            "objects": [
                {"kind": "target", "x": 1.0, "y": 0.5, "size": 0.1, "team": None, "agent": None},
                {"kind": "agent", "x": round(x + 1.0, 6), "y": 0.5, "size": 0.1,
                 "team": "agent", "agent": 0},
            ],  # fmt: skip
        },
        "result": {
            "seed": seed,
            "length": length,
            "scores": {"agent": total},
            "team_rewards": {"agent": total},
            "measures": {},
        },
    }


def point_episode(seed, start, pushes):
    """A 1-D point moving 0.2 per unit push, rewarded -|x|; reaching the target ends it."""
    x, total = start, 0.0
    out = [point_entry(seed, None, 0.0, 0, x, total)]
    for i, push in enumerate(pushes, start=1):
        x = round(x + 0.2 * push, 6)
        reward = round(-abs(x), 6)
        total = round(total + reward, 6)
        out.append(point_entry(seed, [[float(push)]], reward, i, x, total))
    return out


