def run_recording(seed, status="finished"):
    """A 2,000-step snake run folder: 3 checkpoints when finished, 8 eval points when not."""
    name = f"snake-default-s{seed}"
    finished = status == "finished"
    return {
        "record": record(seed, status, ENDED if finished else None),
        "episodes": episodes(seed) if finished else episodes(seed)[:2],
        "evals": eval_points(seed) if finished else eval_points(seed)[:8],
        "checkpoints": [checkpoint(name, pct, 2000) for pct in ([0, 50, 100] if finished else [0])],
    }


def run_writer_calls(rec):
    """The writes of a finished 3-checkpoint run, in the order a training loop makes them."""
    ckpt = [
        {"call": "checkpoint", "pct": c["pct"], "step": c["step"], "state": c["state"],
         "returns": c}
        for c in rec["checkpoints"]
    ]  # fmt: skip
    evals = [{"call": "eval", "point": p} for p in rec["evals"]]
    eps = [{"call": "episode", "result": e} for e in rec["episodes"]]
    close = {"call": "close", "status": "finished", "failure": None, "returns": rec["record"]}
    return [
        ckpt[0], evals[0], *eps[:3], *evals[1:11], ckpt[1], *eps[3:], *evals[11:], ckpt[2], close
    ]  # fmt: skip


