"""How the M1 contract fixtures were made: schemas, samples and recordings (M1-T01).

Run once by the interface task (`python3 tests/contracts/generate.py`); the JSON it wrote is the
frozen contract (CR-09), so this file documents it and is not run again. The snake episodes are
simulated here by the SNAKE-01 to SNAKE-06 rules on a 10 x 10 grid (actions: 0 straight, 1 left,
2 right; headings up, right, down, left), so steps, observations, frames and scores agree.
The corridor check world uses action 0 = left, 1 = right (AD-09).
"""

import json
from pathlib import Path

OUT = Path(__file__).parent


def write(folder, rel, data):
    path = OUT / folder / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=1) + "\n")


# ------------------------------------------------------------------ schemas (JSON Schema)
NUM = {"type": "number"}
INT = {"type": "integer"}
NAT = {"type": "integer", "minimum": 0}
POS = {"type": "integer", "minimum": 1}
STR = {"type": "string"}
BOOL = {"type": "boolean"}
P = {"type": "number", "minimum": 0, "maximum": 1}
DIRECTION = {"enum": ["higher", "lower"]}


def obj(props):
    return {
        "type": "object",
        "properties": props,
        "required": list(props),
        "additionalProperties": False,
    }


def arr(items, n=None):
    d = {"type": "array", "items": items}
    if n is not None:
        d["minItems"] = d["maxItems"] = n
    return d


def ref(name):
    return {"$ref": f"#/$defs/{name}"}


def nullable(s):
    return {"anyOf": [s, {"type": "null"}]}


def mapping(values):
    return {"type": "object", "additionalProperties": values}


DEFS = {
    "ActionSpace": {
        "anyOf": [
            obj({"kind": {"const": "discrete"}, "n": POS}),
            obj({"kind": {"const": "box"}, "dims": POS, "low": NUM, "high": NUM}),
        ]
    },
    "TeamSpec": obj({"name": STR, "agents": arr(NAT), "score_name": STR, "direction": DIRECTION}),
    "MeasureSpec": obj({"name": STR, "team": STR, "direction": DIRECTION}),
    "WorldSpec": obj({
        "world": STR,
        "variant": STR,
        "agents": arr(STR),
        "teams": arr(ref("TeamSpec")),
        "obs_len": POS,
        "action": ref("ActionSpace"),
        "max_steps": POS,
        "measures": arr(ref("MeasureSpec")),
        "sight": nullable(NUM),
    }),
    "Step": obj({
        "obs": arr(arr(NUM)),
        "rewards": arr(NUM),
        "active": arr(BOOL),
        "done": BOOL,
        "truncated": BOOL,
    }),
    "EpisodeResult": obj({
        "seed": INT,
        "length": NAT,
        "scores": mapping(NUM),
        "team_rewards": mapping(NUM),
        "measures": mapping(NUM),
    }),
    "Drawable": obj({
        "kind": STR,
        "x": NUM,
        "y": NUM,
        "size": NUM,
        "team": nullable(STR),
        "agent": nullable(NAT),
    }),
    "DrawState": obj({"width": NUM, "height": NUM, "objects": arr(ref("Drawable"))}),
    "Frame": obj({
        "step": NAT,
        "draw": ref("DrawState"),
        "scores": mapping(NUM),
        "rewards": arr(NUM),
    }),
    "Episode": obj({
        "result": ref("EpisodeResult"),
        "frames": nullable(arr(ref("Frame"))),
        "hit_step_limit": BOOL,
    }),
    "Output": obj({
        "path": STR,
        "kind": {"enum": ["chart", "video", "writeup"]},
        "made_from": arr(STR),
    }),
    "Settings": mapping({"type": ["integer", "number", "string", "boolean"]}),
    "MethodConfig": obj({"method": {"enum": ["dqn", "ppo"]}, "settings": ref("Settings")}),
    "RunConfig": obj({
        "name": STR,
        "world": STR,
        "variant": STR,
        "methods": mapping(ref("MethodConfig")),
        "seed": NAT,
        "budget": POS,
        "check_settings": mapping(ref("Settings")),
        "device": STR,
    }),
    "BaselineMeans": obj({
        "world": STR,
        "variant": STR,
        "random": mapping(NUM),
        "rule": mapping(NUM),
    }),
    "Transition": obj({
        "obs": arr(arr(NUM)),
        "actions": arr({"anyOf": [INT, arr(NUM)]}),
        "rewards": arr(NUM),
        "next_obs": arr(arr(NUM)),
        "done": BOOL,
        "truncated": BOOL,
        "active": arr(BOOL),
    }),
    "CheckResult": obj({"method": STR, "world": STR, "agreement": P, "passed": BOOL}),
    "Failure": obj({"step": NAT, "value": NUM, "checkpoint": STR}),
    "RunRecord": obj({
        "config": ref("RunConfig"),
        "spec": ref("WorldSpec"),
        "started": STR,
        "ended": nullable(STR),
        "status": {"enum": ["running", "finished", "incomplete", "failed"]},
        "failure": nullable(ref("Failure")),
        "path": STR,
    }),
    "EvalPoint": obj({"step": NAT, "scores": mapping(NUM), "measures": mapping(NUM)}),
    "Checkpoint": obj({
        "run": STR,
        "pct": {"enum": list(range(0, 101, 10))},
        "step": NAT,
        "spec": ref("WorldSpec"),
        "methods": mapping(ref("MethodConfig")),
        "state": mapping({"type": "object"}),
        "path": STR,
    }),
    "Progress": obj({
        "step": NAT,
        "budget": POS,
        "latest": nullable(ref("EvalPoint")),
        "elapsed": {"type": "number", "minimum": 0},
        "status": STR,
    }),
    "Comparison": obj({
        "baseline": {"enum": ["random", "rule"]},
        "team": STR,
        "learned_mean": NUM,
        "baseline_mean": NUM,
        "difference": NUM,
        "p_raw": P,
        "p_holm": P,
        "rejected": BOOL,
    }),
    "Verdict": obj({"beats_baselines": BOOL, "failing_runs": arr(STR), "runs_needed": NAT}),
    "Summary": obj({
        "world": STR,
        "variant": STR,
        "team": STR,
        "runs": arr(STR),
        "learned_mean": NUM,
        "learned_range": arr(NUM, 2),
        "run_means": mapping(NUM),
        "random_mean": NUM,
        "rule_mean": NUM,
        "comparisons": arr(ref("Comparison")),
        "verdict": ref("Verdict"),
        "collapse": nullable(NAT),
    }),
}


def refs(node, found):
    if isinstance(node, dict):
        if "$ref" in node:
            name = node["$ref"].rsplit("/", 1)[1]
            if name not in found:
                found.add(name)
                refs(DEFS[name], found)
        for value in node.values():
            refs(value, found)
    elif isinstance(node, list):
        for value in node:
            refs(value, found)


def schema(folder, type_name):
    found = {type_name}
    refs(DEFS[type_name], found)
    write(
        folder,
        "schema.json",
        {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": folder,
            "$ref": f"#/$defs/{type_name}",
            "$defs": {name: DEFS[name] for name in sorted(found)},
        },
    )


# ------------------------------------------------------------------ specs
def team(name, agents, score, direction):
    return {"name": name, "agents": agents, "score_name": score, "direction": direction}


def snake_spec(max_steps=1000):
    return {
        "world": "snake",
        "variant": "default",
        "agents": ["snake"],
        "teams": [team("snake", [0], "food eaten", "higher")],
        "obs_len": 12,
        "action": {"kind": "discrete", "n": 3},
        "max_steps": max_steps,
        "measures": [],
        "sight": None,
    }


BOX2 = {"kind": "box", "dims": 2, "low": -1.0, "high": 1.0}
FISH_LOCAL = {
    "world": "fish",
    "variant": "local",
    "agents": [f"fish-{i}" for i in range(8)],
    "teams": [team("fish", list(range(8)), "hits per fish", "lower")],
    "obs_len": 44,
    "action": BOX2,
    "max_steps": 1000,
    "measures": [],
    "sight": 3.0,
}
PREY_OBS = 40
PREY = {
    "world": "prey",
    "variant": "default",
    "agents": [*(f"prey-{i}" for i in range(6)), "predator-0", "predator-1"],
    "teams": [
        team("prey", list(range(6)), "pellets per prey", "higher"),
        team("predator", [6, 7], "prey caught", "higher"),
    ],
    "obs_len": PREY_OBS,
    "action": BOX2,
    "max_steps": 1000,
    "measures": [{"name": "survivors", "team": "prey", "direction": "higher"}],
    "sight": 4.0,
}
CORRIDOR_SPEC = {
    "world": "check-discrete",
    "variant": "default",
    "agents": ["agent"],
    "teams": [team("agent", [0], "return", "higher")],
    "obs_len": 6,
    "action": {"kind": "discrete", "n": 2},
    "max_steps": 50,
    "measures": [],
    "sight": None,
}
POINT_SPEC = {
    **CORRIDOR_SPEC,
    "world": "check-continuous",
    "obs_len": 1,
    "action": {"kind": "box", "dims": 1, "low": -1.0, "high": 1.0},
    "max_steps": 20,
}


# ------------------------------------------------------------------ snake simulation
HEADINGS = [(0, -1), (1, 0), (0, 1), (-1, 0)]  # up, right, down, left
TURNS = {0: 0, 1: -1, 2: 1}  # straight, left, right


def blocked(cell, body):
    x, y = cell
    return not (0 <= x < 10 and 0 <= y < 10) or cell in body[:-1]


def snake_obs(body, heading, food):
    """Danger straight, left, right; heading one-hot; food up, right, down, left; length."""
    head = body[0]

    def danger(h):
        dx, dy = HEADINGS[h % 4]
        return float(blocked((head[0] + dx, head[1] + dy), body))

    fx, fy = food[0] - head[0], food[1] - head[1]
    return [
        danger(heading),
        danger(heading - 1),
        danger(heading + 1),
        *[float(i == heading) for i in range(4)],
        float(fy < 0),
        float(fx > 0),
        float(fy > 0),
        float(fx < 0),
        float(len(body)),
    ]


def cell(kind, x, y, team_name, agent):
    return {
        "kind": kind,
        "x": float(x),
        "y": float(y),
        "size": 1.0,
        "team": team_name,
        "agent": agent,
    }


def snake_draw(body, food):
    head = [cell("snake-head", *body[0], "snake", 0)]
    rest = [cell("snake-body", x, y, "snake", None) for x, y in body[1:]]
    return {
        "width": 10.0,
        "height": 10.0,
        "objects": [*head, *rest, cell("food", *food, None, None)],
    }


def snake_entry(seed, state, actions_taken, reward, length, truncated):
    body, heading, food, eaten, total = state
    return {
        "actions": actions_taken,
        "step": {
            "obs": [snake_obs(body, heading, food)],
            "rewards": [reward],
            "active": [True],
            "done": truncated,
            "truncated": truncated,
        },
        "draw": snake_draw(body, food),
        "result": {
            "seed": seed,
            "length": length,
            "scores": {"snake": float(eaten)},
            "team_rewards": {"snake": total},
            "measures": {},
        },
    }


def snake_episode(seed, foods, actions, max_steps):
    """Index i: the Step, DrawState and running EpisodeResult after i steps from the centre."""
    body, heading, foods = [(5, 5), (5, 6), (5, 7)], 0, list(foods)
    food, eaten, total = foods.pop(0), 0, 0.0
    out = [snake_entry(seed, (body, heading, food, eaten, total), None, 0.0, 0, False)]
    for i, action in enumerate(actions, start=1):
        heading = (heading + TURNS[action]) % 4
        head = (body[0][0] + HEADINGS[heading][0], body[0][1] + HEADINGS[heading][1])
        assert not blocked(head, body)
        body.insert(0, head)
        reward = float(head == food)
        if reward:
            eaten, food = eaten + 1, foods.pop(0)
        else:
            body.pop()
        total += reward
        state = (body, heading, food, eaten, total)
        out.append(snake_entry(seed, state, [action], reward, i, i == max_steps))
    return out


EP42 = snake_episode(42, [(8, 4), (2, 7)], [0, 2, 0, 0, 2], max_steps=5)
EP7 = snake_episode(7, [(5, 3), (1, 1)], [0, 0, 0], max_steps=3)


def frames(episode):
    return [
        {
            "step": i,
            "draw": entry["draw"],
            "scores": entry["result"]["scores"],
            "rewards": entry["step"]["rewards"],
        }
        for i, entry in enumerate(episode)
    ]


# ------------------------------------------------------------------ check worlds
def corridor_entry(seed, actions_taken, reward, length, state, total):
    obs = [float(i == state) for i in range(6)]
    marker = {"kind": "agent", "x": float(state + 1), "y": 0.0, "size": 1.0, "team": "agent",
              "agent": 0}  # fmt: skip
    return {
        "actions": actions_taken,
        "step": {
            "obs": [obs],
            "rewards": [reward],
            "active": [True],
            "done": state in {-1, 6},
            "truncated": False,
        },
        "draw": {
            "width": 8.0,
            "height": 1.0,
            "objects": [cell("exit", 0, 0, None, None), cell("exit", 7, 0, None, None), marker],
        },
        "result": {
            "seed": seed,
            "length": length,
            "scores": {"agent": total},
            "team_rewards": {"agent": total},
            "measures": {},
        },
    }


def corridor_episode(seed, start, actions):
    """States 0-5; leaving left of 0 pays 0.8, right of 5 pays 1.0 (AD-09)."""
    state, total = start, 0.0
    out = [corridor_entry(seed, None, 0.0, 0, state, total)]
    for i, action in enumerate(actions, start=1):
        state += 1 if action == 1 else -1
        reward = {6: 1.0, -1: 0.8}.get(state, 0.0)
        total += reward
        out.append(corridor_entry(seed, [action], reward, i, state, total))
    return out


CORRIDOR = corridor_episode(0, 2, [1, 1, 1, 1])
CORRIDOR3 = corridor_episode(1, 3, [1, 1, 1])


def point_entry(seed, actions_taken, reward, length, x, total):
    return {
        "actions": actions_taken,
        "step": {
            "obs": [[x]],
            "rewards": [reward],
            "active": [True],
            "done": length > 0 and abs(x) < 0.05,
            "truncated": False,
        },
        "draw": {
            "width": 2.0,
            "height": 1.0,
            "objects": [
                {"kind": "target", "x": 1.0, "y": 0.5, "size": 0.1, "team": None, "agent": None},
