def point_episode(seed, start, pushes):
    """A 1-D point moving 0.2 per unit push, rewarded -|x|; reaching the target ends it."""
    x, total = start, 0.0
    out = [point_entry(seed, None, 0.0, 0, x, total)]
    for i, push in enumerate(pushes, start=1):
        x = round(x + 0.2 * push, 6)
        reward = round(-abs(x), 6)
        total = round(total + reward, 6)
        out.append(point_entry(seed, [[float(push)]], reward, i, x, total))
    return out


